/**
 * Bitbucket Cloud REST API 2.0, through the connection's Named Credential
 * (default RLY_Bitbucket, URL https://api.bitbucket.org/2.0).
 * Token: repository access token with Repositories: read, Pull requests: read, Pipelines: write.
 * Repository is workspace/repository-slug. The pipeline is the custom pipeline named in
 * Workflow file (release-relay), run on the workflow branch with the release values as variables.
 */
public with sharing class RlyBitbucketService extends RlyGitProvider {

    private static final Pattern REPO_PATTERN = Pattern.compile('^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$');
    private static final String API_ROOT = 'https://api.bitbucket.org/2.0';

    private String repo;

    protected override void init(RlySettings.Connection c) {
        super.init(c);
        this.repo = '/repositories/' + c.repository.trim();
    }

    public override Pattern repositoryPattern() { return REPO_PATTERN; }
    public override String repositoryHint() { return 'workspace/repository'; }

    /** Bitbucket redirects some reads (diffs, files); follow within the API through the Named Credential. */
    private HttpResponse get(String path) {
        HttpResponse res = send('GET', path, null, null);
        for (Integer hop = 0; hop < 3 && (res.getStatusCode() == 301 || res.getStatusCode() == 302 || res.getStatusCode() == 307); hop++) {
            String location = res.getHeader('Location');
            if (String.isBlank(location) || !location.startsWith(API_ROOT)) {
                break;
            }
            res = send('GET', location.removeStart(API_ROOT), null, null);
        }
        return res;
    }

    public override Boolean branchExists(String branch) {
        HttpResponse res = get(repo + '/refs/branches/' + RlyGitProvider.enc(branch));
        if (res.getStatusCode() == 404) {
            return false;
        }
        assertOk(res, 'Branch lookup');
        return true;
    }

    public override List<String> listBranches() {
        List<String> names = new List<String>();
        String next = repo + '/refs/branches?pagelen=100';
        for (Integer page = 0; page < 3 && next != null; page++) {
            HttpResponse res = get(next);
            assertOk(res, 'Branch list');
            Map<String, Object> body = (Map<String, Object>) RlyGitProvider.parse(res);
            for (Object o : (List<Object>) body.get('values')) {
                names.add(String.valueOf(((Map<String, Object>) o).get('name')));
            }
            next = body.get('next') == null ? null : String.valueOf(body.get('next')).removeStart(API_ROOT);
        }
        return names;
    }

    public override String getFileRaw(String filePath, String ref) {
        HttpResponse res = get(repo + '/src/' + RlyGitProvider.enc(ref) + '/' + RlyGitProvider.encPath(filePath));
        if (res.getStatusCode() == 404) {
            return null;
        }
        assertOk(res, 'File read');
        return res.getBody();
    }

    public override List<Entry> listDir(String folderPath, String ref) {
        List<Entry> out = new List<Entry>();
        String next = repo + '/src/' + RlyGitProvider.enc(ref) + '/' + RlyGitProvider.encPath(folderPath) + '/?pagelen=100';
        for (Integer page = 0; page < 20 && next != null; page++) {
            HttpResponse res = get(next);
            if (res.getStatusCode() == 404) {
                return out;
            }
            assertOk(res, 'Folder read');
            Map<String, Object> body = (Map<String, Object>) RlyGitProvider.parse(res);
            for (Object o : (List<Object>) body.get('values')) {
                Map<String, Object> m = (Map<String, Object>) o;
                out.add(RlyGitProvider.entry(String.valueOf(m.get('path')).substringAfterLast('/'), m.get('type') == 'commit_directory'));
            }
            next = body.get('next') == null ? null : String.valueOf(body.get('next')).removeStart(API_ROOT);
        }
        return out;
    }

    /** Files changed on head since it left base. */
    public override Comparison compare(String baseRef, String head) {
        HttpResponse res = get(repo + '/diffstat/' + RlyGitProvider.enc(head) + '..' + RlyGitProvider.enc(baseRef) + '?pagelen=100');
        if (res.getStatusCode() == 404) {
            throw new GitException('Branch ' + head + ' or ' + baseRef + ' was not found.');
        }
        assertOk(res, 'Compare');
        Comparison c = new Comparison();
        for (Object o : (List<Object>) ((Map<String, Object>) RlyGitProvider.parse(res)).get('values')) {
            Map<String, Object> d = (Map<String, Object>) o;
            c.files.add(status(d) + '  ' + path(d));
        }
        c.aheadBy = c.files.size();
        c.behindBy = 0;
        c.url = 'https://bitbucket.org/' + conn.repository + '/branches/compare/' + RlyGitProvider.enc(head) + '%0D' + RlyGitProvider.enc(baseRef);
        return c;
    }

    public override Started startPipeline(Map<String, String> inputs) {
        List<Map<String, String>> variables = new List<Map<String, String>>();
        for (String k : inputs.keySet()) {
            variables.add(new Map<String, String>{ 'key' => k.toUpperCase(), 'value' => inputs.get(k) });
        }
        Map<String, Object> body = new Map<String, Object>{
            'target' => new Map<String, Object>{
                'type' => 'pipeline_ref_target', 'ref_type' => 'branch', 'ref_name' => conn.workflowRef,
                'selector' => new Map<String, Object>{ 'type' => 'custom', 'pattern' => conn.workflowFile }
            },
            'variables' => variables
        };
        HttpResponse res = send('POST', repo + '/pipelines/', JSON.serialize(body), null);
        assertOk(res, 'Pipeline start');
        Map<String, Object> m = (Map<String, Object>) RlyGitProvider.parse(res);
        Started s = new Started();
        s.runId = String.valueOf(m.get('uuid'));
        s.url = 'https://bitbucket.org/' + conn.repository + '/pipelines/results/' + String.valueOf(m.get('build_number'));
        return s;
    }

    public override Run findRun(String releaseName, String runMode, String knownRunId) {
        if (String.isBlank(knownRunId)) {
            return null;
        }
        HttpResponse res = get(repo + '/pipelines/' + RlyGitProvider.enc(knownRunId));
        if (res.getStatusCode() == 404) {
            return null;
        }
        assertOk(res, 'Pipeline lookup');
        Map<String, Object> m = (Map<String, Object>) RlyGitProvider.parse(res);
        Map<String, Object> state = (Map<String, Object>) m.get('state');
        String name = state == null ? '' : String.valueOf(state.get('name'));
        Map<String, Object> result = state == null ? null : (Map<String, Object>) state.get('result');
        String outcome = result == null ? null : String.valueOf(result.get('name'));
        Run run = new Run();
        run.id = knownRunId;
        run.url = 'https://bitbucket.org/' + conn.repository + '/pipelines/results/' + String.valueOf(m.get('build_number'));
        run.createdAt = RlyGitProvider.parseTime(m.get('created_on'));
        run.status = name == 'COMPLETED' ? 'completed' : name == 'IN_PROGRESS' ? 'in_progress' : 'queued';
        run.conclusion = name != 'COMPLETED' ? null : outcome == 'SUCCESSFUL' ? 'success' : outcome == 'STOPPED' ? 'cancelled' : 'failure';
        return run;
    }

    public override PullRequest findPullRequest(String branch, String target) {
        String q = 'source.branch.name="' + branch + '" AND destination.branch.name="' + target + '"';
        HttpResponse res = get(repo + '/pullrequests?state=OPEN&state=MERGED&state=DECLINED&state=SUPERSEDED&sort=-created_on&pagelen=1&q='
            + RlyGitProvider.enc(q));
        assertOk(res, 'Pull request lookup');
        List<Object> rows = (List<Object>) ((Map<String, Object>) RlyGitProvider.parse(res)).get('values');
        if (rows == null || rows.isEmpty()) {
            return null;
        }
        Map<String, Object> m = (Map<String, Object>) rows[0];
        PullRequest pr = new PullRequest();
        pr.num = RlyGitProvider.toInt(m.get('id'));
        Map<String, Object> links = (Map<String, Object>) m.get('links');
        pr.url = links == null ? null : String.valueOf(((Map<String, Object>) links.get('html')).get('href'));
        String state = String.valueOf(m.get('state'));
        pr.merged = state == 'MERGED';
        pr.state = state == 'OPEN' ? 'open' : 'closed';
        return pr;
    }

    public override List<PrFile> pullFiles(Integer prNumber, String target, String branch) {
        List<PrFile> out = new List<PrFile>();
        Map<String, PrFile> byPath = new Map<String, PrFile>();
        HttpResponse statRes = get(repo + '/pullrequests/' + prNumber + '/diffstat?pagelen=300');
        assertOk(statRes, 'Pull request files');
        for (Object o : (List<Object>) ((Map<String, Object>) RlyGitProvider.parse(statRes)).get('values')) {
            Map<String, Object> d = (Map<String, Object>) o;
            PrFile f = new PrFile();
            f.filename = path(d);
            f.status = status(d);
            f.additions = RlyGitProvider.toInt(d.get('lines_added'));
            f.deletions = RlyGitProvider.toInt(d.get('lines_removed'));
            f.patch = '';
            f.truncated = false;
            out.add(f);
            byPath.put(f.filename, f);
        }
        HttpResponse diff = get(repo + '/pullrequests/' + prNumber + '/diff');
        if (diff.getStatusCode() == 200) {
            Integer budget = 2000000;
            for (String chunk : diff.getBody().split('(?m)^diff --git ')) {
                String header = chunk.substringBefore('\n');
                String file = header.substringAfterLast(' b/').trim();
                PrFile f = byPath.get(file);
                if (f != null && chunk.contains('\n@@')) {
                    budget = RlyGitProvider.fitPatch(f, chunk.substring(chunk.indexOf('\n@@') + 1), budget);
                }
            }
        }
        return out;
    }

    private static String path(Map<String, Object> d) {
        Map<String, Object> n = (Map<String, Object>) d.get('new');
        Map<String, Object> o = (Map<String, Object>) d.get('old');
        return String.valueOf((n != null ? n : o).get('path'));
    }

    private static String status(Map<String, Object> d) {
        String s = String.valueOf(d.get('status'));
        return s == 'added' ? 'added' : s == 'removed' ? 'removed' : s == 'renamed' ? 'renamed' : 'modified';
    }
}
